import{_ as a,c as t,o,a5 as i}from"./chunks/framework.DIf8AhXT.js";const u=JSON.parse('{"title":"Shipping","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"faq/shipping.md","filePath":"faq/shipping.md"}'),r={name:"faq/shipping.md"};function s(n,e,h,c,l,d){return o(),t("div",{"data-pagefind-body":!0},e[0]||(e[0]=[i('<h1 id="shipping" tabindex="-1">Shipping <a class="header-anchor" href="#shipping" aria-label="Permalink to &quot;Shipping&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#do-you-ship-internationally">Do you ship internationally? ​</a></li><li><a href="#how-fast-can-i-get-my-devices">How fast can I get my devices? ​</a></li><li><a href="#will-i-have-to-pay-customs-or-import-fees">Will I have to pay customs or import fees? ​</a></li><li><a href="#my-order-is-on-hold-at-customs-what-should-i-do">My order is on hold at customs, what should I do? ​</a></li><li><a href="#what-if-my-country-isn-t-listed-at-checkout">What if my country isn&#39;t listed at checkout ​</a></li><li><a href="#can-i-change-my-shipping-address-after-placing-the-order">Can I change my shipping address after placing the order ? ​</a></li><li><a href="#i-haven-t-received-my-order-or-shipping-confirmation">I haven&#39;t received my order or shipping confirmation? ​</a></li></ul></nav><h2 id="do-you-ship-internationally" tabindex="-1">Do you ship internationally? <a class="header-anchor" href="#do-you-ship-internationally" aria-label="Permalink to &quot;Do you ship internationally?&quot;">​</a></h2><p>Yes, we ship to most countries!</p><p>Shipping costs and times will be shown during checkout.</p><h2 id="how-fast-can-i-get-my-devices" tabindex="-1">How fast can I get my devices? <a class="header-anchor" href="#how-fast-can-i-get-my-devices" aria-label="Permalink to &quot;How fast can I get my devices?&quot;">​</a></h2><p>For all items in stock, we aim to dispatch your order within 1-3 days. Shipping times will vary.</p><p>Dispatch time: It can take 1-3 days for your order to be processed, packaged and collected by the courier from our office.</p><p>Shipping time: Shipping times will be shown at checkout after you enter your address. This is approximately how long it will take for your order to arrive once it has collected by the courier from our office.</p><h2 id="will-i-have-to-pay-customs-or-import-fees" tabindex="-1">Will I have to pay customs or import fees? <a class="header-anchor" href="#will-i-have-to-pay-customs-or-import-fees" aria-label="Permalink to &quot;Will I have to pay customs or import fees?&quot;">​</a></h2><p>We will prepare all the required documentation for international shipping, however Lightbug does not take responsibility for any customs or import fees that may occur once your order reaches its destination country, the customer must cover these charges.</p><p>We have very little control over these charges, and cannot accurately tell you how much these would be as they vary widely from country to country.</p><p>If you have any queries regarding possible customs and fees, we recommend reaching out to your local customs office.</p><h2 id="my-order-is-on-hold-at-customs-what-should-i-do" tabindex="-1">My order is on hold at customs, what should I do? <a class="header-anchor" href="#my-order-is-on-hold-at-customs-what-should-i-do" aria-label="Permalink to &quot;My order is on hold at customs, what should I do?&quot;">​</a></h2><p>If your order is on hold at customs please contact your local customs office or shipping courier.</p><p>If you&#39;re still facing problems, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">reach out to us</a>.</p><h2 id="what-if-my-country-isn-t-listed-at-checkout" tabindex="-1">What if my country isn&#39;t listed at checkout <a class="header-anchor" href="#what-if-my-country-isn-t-listed-at-checkout" aria-label="Permalink to &quot;What if my country isn&#39;t listed at checkout&quot;">​</a></h2><p>If your country isn&#39;t listed at checkout, please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact us</a> and we&#39;ll see what we can do.</p><h2 id="can-i-change-my-shipping-address-after-placing-the-order" tabindex="-1">Can I change my shipping address after placing the order ? <a class="header-anchor" href="#can-i-change-my-shipping-address-after-placing-the-order" aria-label="Permalink to &quot;Can I change my shipping address after placing the order ?&quot;">​</a></h2><p>Our shipping team may have already started processing your order, however, we may be able to amend your shipping address before dispatch.</p><p>Please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">get in touch</a> with us as soon as possible if you need to change your shipping address.</p><h2 id="i-haven-t-received-my-order-or-shipping-confirmation" tabindex="-1">I haven&#39;t received my order or shipping confirmation? <a class="header-anchor" href="#i-haven-t-received-my-order-or-shipping-confirmation" aria-label="Permalink to &quot;I haven&#39;t received my order or shipping confirmation?&quot;">​</a></h2><p>It may be that your confirmation emails have gone to your spam or junk mail so we recommend that you check there first.</p><p>If you still cannot find your confirmation, it may be that we have an incorrect email address for you.</p><p>Please <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact us</a> with the full name the order was placed under.</p>',25)]))}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
